1	package main
2	
3	import (
4		"fmt"
5		"sort"
6	)
7	
8	// 周期保养计划与完成登记。
9	//
10	// 日期一律为 0001 至 9999 年的公历日历日（YYYY-MM-DD），按日历日运算：
11	// 不涉及时区与运行时刻，内部以“距 0001-01-01 的天数”做整数运算，避免
12	// time.Time 的时区、跨度（time.Duration 约 292 年上限）与年份范围问题。
13	//
14	// 每个计划恰有一条建立履历（含初始计划：内容、首次到期日、间隔天数），
15	// 每次完成登记追加一条完成履历（含周期到期日、实际完成日、结果），每次撤销
16	// 误登记追加一条撤销履历（含目标完成履历序号、理由）。计划的下一到期日由
17	// 履历链推出并保存在计划中，加载与保存时核对二者一致。
18	// 保养不创建或终结工单、不消耗工单编号，不改变资产状态、请求绑定或停机统计。
19	
20	// Plan 为资产的周期保养计划；每项资产最多一个，不可覆盖。
21	// NextDue 为由履历链推出的下一到期日，随每次完成登记推进。
22	type Plan struct {
23		AssetID      string `json:"asset_id"`
24		Content      string `json:"content"`
25		FirstDue     string `json:"first_due"`
26		IntervalDays int    `json:"interval_days"`
27		NextDue      string `json:"next_due"`
28	}
29	
30	// maxDayNum 为 9999-12-31 的日序号（0001-01-01 为 0）。
31	const maxDayNum = 3652058
32	
33	// daysFromCivil 返回公历日期距 0001-01-01 的天数（该日为 0）。
34	// 输入须为 0001 至 9999 年间的有效日期（由 parseDate 保证）。
35	func daysFromCivil(y, m, d int) int64 {
36		yy := int64(y)
37		if m <= 2 {
38			yy--
39		}
40		era := yy / 400
41		yoe := yy - era*400
42		mp := int64((m + 9) % 12)
43		doy := (153*mp+2)/5 + int64(d) - 1
44		doe := yoe*365 + yoe/4 - yoe/100 + doy
45		return era*146097 + doe - 306
46	}
47	
48	// civilFromDays 为 daysFromCivil 的逆运算。
49	func civilFromDays(n int64) (int, int, int) {
50		z := n + 306
51		era := z / 146097
52		doe := z - era*146097
53		yoe := (doe - doe/1460 + doe/36524 - doe/146096) / 365
54		y := yoe + era*400
55		doy := doe - (365*yoe + yoe/4 - yoe/100)
56		mp := (5*doy + 2) / 153
57		d := doy - (153*mp+2)/5 + 1
58		if mp < 10 {
59			return int(y), int(mp + 3), int(d)
60		}
61		return int(y + 1), int(mp - 9), int(d)
62	}
63	
64	func isLeapYear(y int) bool {
65		return y%4 == 0 && (y%100 != 0 || y%400 == 0)
66	}
67	
68	func daysInMonth(y, m int) int {
69		switch m {
70		case 1, 3, 5, 7, 8, 10, 12:
71			return 31
72		case 4, 6, 9, 11:
73			return 30
74		}
75		if isLeapYear(y) {
76			return 29
77		}
78		return 28
79	}
80	
81	// atoiN 解析定长十进制数字串；含非数字字符时 ok=false。
82	func atoiN(s string) (int, bool) {
83		n := 0
84		for i := 0; i < len(s); i++ {
85			if s[i] < '0' || s[i] > '9' {
86				return 0, false
87			}
88			n = n*10 + int(s[i]-'0')
89		}
90		return n, true
91	}
92	
93	// parseDate 解析 YYYY-MM-DD 形式的公历日期（0001 至 9999 年，须为零填充的
94	// 完整形式），返回日序号。闰日等按公历规则校验。
95	func parseDate(s string) (int64, error) {
96		if len(s) != 10 || s[4] != '-' || s[7] != '-' {
97			return 0, fmt.Errorf("不是 YYYY-MM-DD 形式: %q", s)
98		}
99		y, ok1 := atoiN(s[0:4])
100		m, ok2 := atoiN(s[5:7])
101		d, ok3 := atoiN(s[8:10])
102		if !ok1 || !ok2 || !ok3 {
103			return 0, fmt.Errorf("不是 YYYY-MM-DD 形式: %q", s)
104		}
105		if y < 1 || m < 1 || m > 12 || d < 1 || d > daysInMonth(y, m) {
106			return 0, fmt.Errorf("不是 0001 至 9999 年间的有效公历日期: %q", s)
107		}
108		return daysFromCivil(y, m, d), nil
109	}
110	
111	// formatDate 把日序号格式化为 YYYY-MM-DD。
112	func formatDate(n int64) string {
113		y, m, d := civilFromDays(n)
114		return fmt.Sprintf("%04d-%02d-%02d", y, m, d)
115	}
116	
117	// nextDueAfter 返回首次到期日加整数倍间隔所得日期中，严格晚于 after 的最早
118	// 日期。结果超出 9999-12-31 时 ok=false。间隔必须为正整数。
119	func nextDueAfter(first, interval, after int64) (int64, bool) {
120		var k int64
121		if after >= first {
122			k = (after-first)/interval + 1
123		}
124		// k ≥ 1 且间隔本身已超出剩余日期范围时，结果必然越界；先判断避免溢出。
125		if k > 0 && interval > maxDayNum-first {
126			return 0, false
127		}
128		n := first + k*interval
129		if n > maxDayNum {
130			return 0, false
131		}
132		return n, true
133	}
134	
135	// findPlan 返回资产的保养计划，无计划时返回 nil。
136	func (s *store) findPlan(assetID string) *Plan {
137		for _, p := range s.data.Plans {
138			if p.AssetID == assetID {
139				return p
140			}
141		}
142		return nil
143	}
144	
145	// appendMaintEvent 以给定序号追加保养履历（建立或完成）。保养履历不属于任何
146	// 工单，from/to 恒为空；due/done/interval 按履历类型使用。
147	func (s *store) appendMaintEvent(seq int, assetID, kind, content, due, done string, interval int) {
148		s.data.Events = append(s.data.Events, Event{
149			Seq:      seq,
150			AssetID:  assetID,
151			Kind:     kind,
152			Content:  content,
153			Due:      due,
154			Done:     done,
155			Interval: interval,
156			Time:     s.now(),
157		})
158	}
159	
160	// createPlan 为资产建立唯一的周期保养计划：每项资产最多一个，已有计划时拒绝，
161	// 不覆盖。成功时追加一条含初始计划的建立履历，下一到期日即首次到期日。
162	// 失败路径不修改任何业务数据。
163	func (s *store) createPlan(assetID, content, firstDue string, intervalDays int) (*Plan, error) {
164		if s.findAsset(assetID) == nil {
165			return nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
166		}
167		if s.findPlan(assetID) != nil {
168			return nil, fmt.Errorf("%w: 资产 %s 已有保养计划，不能重复建立或覆盖", errConflict, assetID)
169		}
170		if content == "" {
171			return nil, fmt.Errorf("%w: 保养内容不能为空", errConflict)
172		}
173		if intervalDays < 1 {
174			return nil, fmt.Errorf("%w: 保养间隔天数须为正整数", errConflict)
175		}
176		if _, err := parseDate(firstDue); err != nil {
177			return nil, fmt.Errorf("%w: 首次到期日无效：%s", errConflict, err)
178		}
179		eventSeq, err := s.nextEventSeq()
180		if err != nil {
181			return nil, err
182		}
183		p := &Plan{
184			AssetID:      assetID,
185			Content:      content,
186			FirstDue:     firstDue,
187			IntervalDays: intervalDays,
188			NextDue:      firstDue,
189		}
190		s.data.Plans = append(s.data.Plans, p)
191		s.appendMaintEvent(eventSeq, assetID, eventPlanCreate, content, firstDue, "", intervalDays)
192		return p, nil
193	}
194	
195	// completePlan 登记当前周期的保养完成：所填到期日必须等于当前下一到期日
196	// （旧周期不能重复登记，也不能登记尚未到期的新周期），实际完成日不得早于
197	// 周期到期日。成功时追加一条完成履历，并把下一到期日推进到首次到期日加整数倍
198	// 间隔所得日期中严格晚于完成日的最早日期；延期跨过的周期不生成完成记录。
199	// 若下一到期日超出 9999-12-31，整次拒绝。返回完成履历的全库序号。
200	// 失败路径不修改任何业务数据。
201	func (s *store) completePlan(assetID, due, done, result string) (*Plan, string, int, error) {
202		if s.findAsset(assetID) == nil {
203			return nil, "", 0, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
204		}
205		p := s.findPlan(assetID)
206		if p == nil {
207			return nil, "", 0, fmt.Errorf("%w: 资产 %s 没有保养计划", errNotFound, assetID)
208		}
209		if a := s.findAsset(assetID); a != nil && a.Status == statusDeactivated {
210			// 停用期间拒绝保养完成登记；停用不暂停或重算周期，保存的下一到期日不变。
211			return nil, "", 0, fmt.Errorf("%w: 资产 %s 已停用，不能登记保养完成", errConflict, assetID)
212		}
213		if result == "" {
214			return nil, "", 0, fmt.Errorf("%w: 保养结果不能为空", errConflict)
215		}
216		dueN, err := parseDate(due)
217		if err != nil {
218			return nil, "", 0, fmt.Errorf("%w: 周期到期日无效：%s", errConflict, err)
219		}
220		doneN, err := parseDate(done)
221		if err != nil {
222			return nil, "", 0, fmt.Errorf("%w: 实际完成日无效：%s", errConflict, err)
223		}
224		if due != p.NextDue {
225			return nil, "", 0, fmt.Errorf(
226				"%w: 周期到期日 %s 与资产 %s 当前下一到期日 %s 不符（旧周期不能重复登记，也不能登记新周期）",
227				errConflict, due, assetID, p.NextDue)
228		}
229		if doneN < dueN {
230			return nil, "", 0, fmt.Errorf("%w: 实际完成日 %s 早于周期到期日 %s", errConflict, done, due)
231		}
232		first, _ := parseDate(p.FirstDue)
233		next, ok := nextDueAfter(first, int64(p.IntervalDays), doneN)
234		if !ok {
235			return nil, "", 0, fmt.Errorf(
236				"%w: 按完成日 %s 推算的下一到期日超出 9999-12-31，无法登记本次完成", errConflict, done)
237		}
238		eventSeq, err := s.nextEventSeq()
239		if err != nil {
240			return nil, "", 0, err
241		}
242		p.NextDue = formatDate(next)
243		s.appendMaintEvent(eventSeq, assetID, eventPlanDone, result, due, done, 0)
244		return p, p.NextDue, eventSeq, nil
245	}
246	
247	// revokedDoneSeqs 返回已被撤销的保养完成履历序号集合。
248	func (s *store) revokedDoneSeqs() map[int]bool {
249		revoked := map[int]bool{}
250		for _, e := range s.data.Events {
251			if e.Kind == eventPlanRevoke {
252				revoked[e.TargetSeq] = true
253			}
254		}
255		return revoked
256	}
257	
258	// revokeCompletion 撤销误登记的保养完成：目标须为该资产按序号最新的未撤销完成
259	// （存在更晚有效完成时拒绝；撤销后可继续撤销此前最新有效完成）。成功时保留原
260	// 完成的日期、结果与时间，追加一条含目标序号、理由与操作时间的撤销履历，并把
261	// 下一到期日恢复为该完成的周期到期日（延期跨过的周期不补记录）。维修或其他
262	// 资产事件不阻止撤销。失败路径不修改任何业务数据。
263	func (s *store) revokeCompletion(assetID string, targetSeq int, reason string) (*Plan, *Event, error) {
264		if s.findAsset(assetID) == nil {
265			return nil, nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
266		}
267		if reason == "" {
268			return nil, nil, fmt.Errorf("%w: 撤销理由不能为空", errConflict)
269		}
270		p := s.findPlan(assetID)
271		if p == nil {
272			return nil, nil, fmt.Errorf("%w: 资产 %s 没有保养计划", errNotFound, assetID)
273		}
274		var target *Event
275		for i := range s.data.Events {
276			if s.data.Events[i].Seq == targetSeq {
277				target = &s.data.Events[i]
278				break
279			}
280		}
281		if target == nil {
282			return nil, nil, fmt.Errorf("%w: 未知履历序号 %d", errNotFound, targetSeq)
283		}
284		if target.Kind != eventPlanDone || target.AssetID != assetID {
285			return nil, nil, fmt.Errorf("%w: 履历序号 %d 不是资产 %s 的保养完成履历", errConflict, targetSeq, assetID)
286		}
287		revoked := s.revokedDoneSeqs()
288		if revoked[targetSeq] {
289			return nil, nil, fmt.Errorf("%w: 完成履历序号 %d 已撤销，不能重复撤销", errConflict, targetSeq)
290		}
291		latest := 0
292		for _, e := range s.data.Events {
293			if e.AssetID == assetID && e.Kind == eventPlanDone && !revoked[e.Seq] && e.Seq > latest {
294				latest = e.Seq
295			}
296		}
297		if latest != targetSeq {
298			return nil, nil, fmt.Errorf(
299				"%w: 完成履历序号 %d 不是资产 %s 最新的有效完成（当前为序号 %d），存在更晚有效完成时不能撤销",
300				errConflict, targetSeq, assetID, latest)
301		}
302		eventSeq, err := s.nextEventSeq()
303		if err != nil {
304			return nil, nil, err
305		}
306		p.NextDue = target.Due
307		s.data.Events = append(s.data.Events, Event{
308			Seq:       eventSeq,
309			AssetID:   assetID,
310			Kind:      eventPlanRevoke,
311			Content:   reason,
312			TargetSeq: targetSeq,
313			Time:      s.now(),
314		})
315		return p, target, nil
316	}
317	
318	// duePlanRow 为到期查询的一行结果。
319	type duePlanRow struct {
320		AssetID string
321		Name    string
322		Content string
323		Due     string
324	}
325	
326	// duePlans 列出下一到期日不晚于 date 的保养计划，按到期日再按资产编号排序。
327	// 停用资产不参与到期查询：停用不暂停或重算周期，保存的下一到期日保持不变，
328	// 恢复使用后仍按该日期参与查询，逾期计划显示原到期日。
329	// 只读：不写文件、不初始化目录、不推进计划。date 须为有效日期（调用方校验）。
330	func (s *store) duePlans(date string) []duePlanRow {
331		rows := make([]duePlanRow, 0)
332		for _, p := range s.data.Plans {
333			// YYYY-MM-DD 零填充形式的字典序即时间顺序。
334			if p.NextDue > date {
335				continue
336			}
337			a := s.findAsset(p.AssetID)
338			if a == nil {
339				continue // 整库一致性检查已保证归属；防御性跳过
340			}
341			if a.Status == statusDeactivated {
342				continue
343			}
344			rows = append(rows, duePlanRow{AssetID: p.AssetID, Name: a.Name, Content: p.Content, Due: p.NextDue})
345		}
346		sort.Slice(rows, func(i, j int) bool {
347			if rows[i].Due != rows[j].Due {
348				return rows[i].Due < rows[j].Due
349			}
350			return rows[i].AssetID < rows[j].AssetID
351		})
352		return rows
353	}
