		if _, err := s.createPlan("EQ-1", "更换滤芯", bad, 90); !errors.Is(err, errConflict) {
			t.Fatalf("日期 %q 应失败，得到 %v", bad, err)
		}
	}
	if len(s.data.Plans) != 0 || len(s.data.Events) != 0 {
		t.Fatal("失败的建立不应产生计划或履历")
	}

