		t.Fatal(err)
	}

	// 未知资产、无计划、空内容、空理由、非正间隔、无效日期均拒绝。
	if _, _, err := s.adjustPlan("NOPE", "新内容", "2027-01-01", 60, "理由"); !errors.Is(err, errNotFound) {
