	if old.Content != "更换滤芯" || old.FirstDue != "2026-11-01" || old.IntervalDays != 90 || old.NextDue != "2026-11-01" {
		t.Fatalf("原方案快照不对: %+v", old)
	}
	if p.Content != "更换高效滤芯" || p.FirstDue != "2027-01-01" || p.IntervalDays != 60 || p.NextDue != "2027-01-01" {
